pub const ORG_MEMBER: i16 = 1;
pub const ORG_ADMIN: i16 = 2;
pub const ORG_OWNER: i16 = 3;
pub const P_VIEWER: i16 = 1;
pub const P_DEV: i16 = 2;
pub const P_ADMIN: i16 = 3;

