    drop(listener);
    tokio::select! {
        _ = graceful.shutdown() => {}
        _ = tokio::time::sleep(Duration::from_secs(10)) => {}
    }
    std::process::exit(0);
}

async fn handle(app: Arc<App>, req: Request<Incoming>) -> Result<Resp, Infallible> {
    Ok(match route(app, req).await {
        Ok(r) => r,
        Err(e) => err_resp(&e),
    })
}

