use std::sync::LazyLock;

use serde::Serialize;
use uuid::Uuid;

use crate::issues::{issue_ctx, issue_from_row, Issue, ISSUE_COLS};
use crate::util::*;
use crate::webhooks;

#[derive(Serialize)]
pub struct CommentOut {
    pub id: Uuid,
    pub issue_key: String,
    pub author_id: Uuid,
    pub body: String,
    pub created_at: Ts,
    pub updated_at: Ts,
    pub edited: bool,
